function thumbCandidates(v){const out=[];if(v.thumbnail)out.push(v.thumbnail);if(v.youtubeId)out.push(`https://i.ytimg.com/vi/${encodeURIComponent(v.youtubeId)}/hqdefault.jpg`);if(v.descriptionImage)out.push(v.descriptionImage);out.push(brandImage(v));return [...new Set(out.filter(Boolean))]}
