function closeMenus(){document.querySelectorAll('.filter-menu').forEach(x=>x.classList.add('hidden'));document.querySelectorAll('.filter-btn').forEach(x=>x.classList.remove('open'))}
function card(v){const k=key(v),w=state.watch[k],done=Boolean(w?.completedAt),pos=Number(w?.position||0),dur=parseDuration(v.duration||''),progress=pos&&dur<1e8?Math.min(100,pos/dur*100):0,tags=(v.tags||[]).slice(0,2);return `<article class="card" tabindex="0" data-key="${esc(k)}"><div class="thumb"><div class="thumb-placeholder"><div class="ph-kicker">BINI VAULT</div><div class="ph-title">${esc(v.title||'BINI video')}</div></div><img class="thumb-img" loading="lazy" decoding="async" alt="" referrerpolicy="no-referrer" data-key="${esc(k)}"><span class="badge">${esc(v.duration||'VIDEO')}</span><span class="play">▶</span><button class="card-more" aria-label="More">⋯</button>${cardState(v)?`<span class="card-state">${cardState(v)}</span>`:''}${progress?`<span class="progress-mini"><i style="width:${progress}%"></i></span>`:''}</div><div class="card-title">${esc(v.title||'Untitled BINI video')}</div>${tags.length?`<div class="card-tags">${tags.map((t,i)=>`<span class="tag ${i===0?'accent':''}">${esc(t)}</span>`).join('')}</div>`:''}</article>`}
