function continueItems(){return Object.entries(state.watch).map(([k,w])=>({key:k,w})).filter(x=>x.w&&!x.w.completedAt).sort((a,b)=>(b.w.updatedAt||b.w.startedAt||0)-(a.w.updatedAt||a.w.startedAt||0)).slice(0,6)}function renderContinue(){const items=continueItems();el.continueSection.innerHTML=items.length?`<section class="section"><div class="section-head"><div class="section-title"><h2>Continue Watching</h2><p>Pick up where you left off.</p></div><small>${items.length} in progress</small></div><div class="mini-grid">${items.map(({w})=>{const v=storedToVideo(w);return card(v)}).join('')}</div></section>`:'';bindCards(el.continueSection);observeThumbs(el.continueSection)}function storedToVideo(w){return {...w}}
