function historyItems(){return Object.entries(state.history).map(([k,v])=>({k,v})).sort((a,b)=>(b.v.openedAt||0)-(a.v.openedAt||0))}function renderHistoryPage(){const items=historyItems();el.historySection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Your archive activity</div><h1 class="page-title">Watch History</h1><p class="page-subtitle">Everything you opened on this device, ordered by most recent.</p></div><div class="section-head"><div class="section-title"><h2>${items.length} recently opened</h2><p>Your history stays local to this browser.</p></div><div class="history-actions"><button id="clearHistory">Clear history</button></div></div>${items.length?`<div class="video-grid">${items.map(x=>card(x.v)).join('')}</div>`:`<div class="empty-hero"><div class="empty-icon">◷</div><h3>Your history is waiting</h3><p>Open a BINI video and it will appear here.</p><button class="btn btn-primary" id="historyBrowse">Browse the Vault</button></div>`}</section>`;bindCards(el.historySection);observeThumbs(el.historySection);el.historySection.querySelector('#clearHistory')?.addEventListener('click',()=>{if(!confirm('Clear watch history on this device?'))return;state.history={};localStorage.setItem('bini-vault-history','{}');renderCurrentView();renderStats();toast('History cleared')});el.historySection.querySelector('#historyBrowse')?.addEventListener('click',navBrowse)}
function renderMyListPage(){const items=[...state.myList].map(k=>state.listSnapshots[k]).filter(Boolean);el.myListSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Saved locally</div><h1 class="page-title">My List</h1><p class="page-subtitle">A personal shelf for videos you want to come back to.</p></div><div class="section-head"><div class="section-title"><h2>${items.length} saved videos</h2></div></div>${items.length?`<div class="video-grid">${items.map(card).join('')}</div>`:`<div class="empty-hero"><div class="empty-icon">♡</div><h3>Your list is waiting for its first BINI moment</h3><p>Save videos from any card or the player to build your personal shelf.</p><button class="btn btn-primary" id="myListBrowse">Browse the Vault</button></div>`}</section>`;bindCards(el.myListSection);observeThumbs(el.myListSection);el.myListSection.querySelector('#myListBrowse')?.addEventListener('click',navBrowse)}
function renderCollectionsPage(){el.collectionsSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Curated for fans</div><h1 class="page-title">Collections</h1><p class="page-subtitle">Explore the archive by theme instead of scrolling one endless catalog.</p></div><div class="collection-grid">${COLLECTIONS.map(c=>`<article class="collection-card" data-collection="${c.id}"><img src="${c.image}" loading="lazy" alt=""><div class="collection-copy"><span class="collection-count">Collection</span><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p></div></article>`).join('')}</div></section>`;el.collectionsSection.querySelectorAll('[data-collection]').forEach(n=>n.onclick=()=>{const c=COLLECTIONS.find(x=>x.id===n.dataset.collection);if(!c)return;state.source=c.source||'all';state.tag=c.tag||'';state.member=c.tag||'';state.year=c.year||'';state.query=c.query||'';state.sortMode=c.sort||'newest';state.view='browse';setActiveNav('browse');renderCurrentView();loadPage(true);toast(`${c.title} opened`);scrollTo({top:0,behavior:'smooth'})})}
function renderOnThisDay(){const now=new Date(),mm=String(now.getMonth()+1).padStart(2,'0'),dd=String(now.getDate()).padStart(2,'0');const items=sortVideos([...state.allLoaded.values()].filter(v=>{const d=String(v.date||'');return d.includes(`-${mm}-${dd}`)||d.includes(`/${mm}/${dd}`)})).slice(0,3);el.onThisDaySection.innerHTML=items.length?`<section class="section"><div class="section-head"><div class="section-title"><h2>On This Day</h2><p>Archive moments from this date in previous years.</p></div></div><div class="onthisday">${items.map(v=>`<article class="otd-card" onclick='window.__openByKey(${JSON.stringify(key(v))})'><div class="otd-date">${esc(v.date||'Archive')}</div><h3>${esc(v.title)}</h3><p>${esc(v.sourceName||'BINI Vault')}</p></article>`).join('')}</div></section>`:''}
function renderHome(){el.hero.classList.remove('view-hidden');el.browsebar.classList.remove('view-hidden');el.stats.classList.remove('view-hidden');el.continueSection.classList.remove('view-hidden');el.myListSection.classList.remove('view-hidden');el.historySection.classList.add('view-hidden');el.onThisDaySection.classList.remove('view-hidden');el.collectionsSection.classList.remove('view-hidden');el.specialSection.classList.add('view-hidden');el.content.innerHTML='';renderTabs();renderActions();renderStats();renderContinue();renderMyListHome();renderOnThisDay();el.collectionsSection.innerHTML=`<section class="section"><div class="section-head"><div class="section-title"><h2>Explore the Vault</h2><p>Curated collections for quick discovery.</p></div><button class="view-all" onclick="window.__navCollections()">See all collections</button></div><div class="collection-grid">${COLLECTIONS.slice(0,4).map(c=>`<article class="collection-card" data-collection="${c.id}"><img src="${c.image}" loading="lazy" alt=""><div class="collection-copy"><span class="collection-count">Curated</span><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p></div></article>`).join('')}</div></section>`;el.collectionsSection.querySelectorAll('[data-collection]').forEach(n=>n.onclick=()=>{const c=COLLECTIONS.find(x=>x.id===n.dataset.collection);state.source=c.source||'all';state.tag=c.tag||'';state.member=c.tag||'';state.year=c.year||'';state.query=c.query||'';state.sortMode=c.sort||'newest';state.view='browse';setActiveNav('browse');renderCurrentView();loadPage(true)});renderCatalog();el.sentinel.classList.remove('view-hidden')}
function renderCatalog(){const title=state.query?`Search results for “${esc(state.query)}”`:state.tag?`${esc(state.tag)} videos`:state.year?`BINI ${esc(state.year)}`:collectionName();const subtitle=state.query?'Matching videos from the vault.':SOURCE_SUBTITLES[state.source]||'BINI videos from the vault.';const loaded=state.videos.length;el.content.innerHTML=loaded?`<section class="section catalog-section"><div class="section-head"><div class="section-title"><h2>${title}</h2><p>${subtitle}</p></div><small>${loaded}${state.hasMore?'+':''} loaded</small></div><div class="video-grid" id="videoGrid">${state.videos.map(card).join('')}</div><div class="grid-loading hidden" id="gridLoading">${Array.from({length:6},()=>'<div class="skeleton-video"><div class="skeleton-thumb"></div><div class="skeleton-text"></div><div class="skeleton-text short"></div></div>').join('')}</div></section>`:`<div class="empty-hero"><div class="empty-icon">⌕</div><h3>No BINI videos found</h3><p>Try a different search, member, year, or collection.</p><button class="btn btn-secondary" id="clearSearchBtn">Clear filters</button></div>`;bindCards(el.content);observeThumbs(el.content);el.content.querySelector('#clearSearchBtn')?.addEventListener('click',()=>{state.query='';state.tag='';state.year='';state.member=null;state.source='all';state.view='browse';renderActions();loadPage(true)})}
function renderSpecialView(kind){if(kind==='members'){el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Explore by member</div><h1 class="page-title">Members</h1><p class="page-subtitle">Jump straight into a member's archive moments.</p></div><div class="member-grid">${MEMBERS.map((m,i)=>`<article class="member-card" data-member-page="${esc(m)}"><img class="member-avatar" src="${BRAND_IMAGES[i%BRAND_IMAGES.length]}" alt=""><div><div class="member-name">${esc(m)}</div><div class="member-sub">Open member archive →</div></div></article>`).join('')}</div></section>`;el.specialSection.querySelectorAll('[data-member-page]').forEach(n=>n.onclick=()=>{state.tag=n.dataset.memberPage;state.member=n.dataset.memberPage;state.source='all';state.year='';state.query='';state.view='browse';setActiveNav('browse');renderCurrentView();loadPage(true);scrollTo({top:0,behavior:'smooth'})})}else if(kind==='timeline'){el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Archive history</div><h1 class="page-title">Era Timeline</h1><p class="page-subtitle">Browse the Vault through the eras and years that shaped BINI's archive.</p></div><div class="timeline">${ERAS.map(e=>`<article class="timeline-card"><div class="timeline-year">${e.year}</div><div><div class="timeline-era">${e.name}</div><div class="timeline-desc">${e.desc}</div></div><button class="small-btn" data-era="${e.year}">Browse</button></article>`).join('')}</div></section>`;el.specialSection.querySelectorAll('[data-era]').forEach(b=>b.onclick=()=>{state.year=b.dataset.era;state.source='all';state.tag='';state.member=null;state.query='';state.view='browse';setActiveNav('browse');renderCurrentView();loadPage(true);scrollTo({top:0,behavior:'smooth'})})}else if(kind==='playlists'){el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Personal library</div><h1 class="page-title">Playlists</h1><p class="page-subtitle">Keep private collections of your favorite performances, comfort videos, and watch-later picks.</p></div><div class="list-tools"><button class="btn btn-primary" id="newPlaylist">＋ New Playlist</button><button class="btn btn-secondary" id="exportData">Export Vault Data</button><button class="btn btn-tertiary" id="importData">Import Vault Data</button></div><div class="playlist-grid" id="playlistGrid" style="margin-top:14px">${Object.keys(state.playlists).length?Object.entries(state.playlists).map(([name,items])=>`<article class="playlist-card"><h3>${esc(name)}</h3><p>${items.length} saved videos</p><button class="small-btn" data-playlist="${esc(name)}">Open</button></article>`).join(''):`<div class="empty-hero" style="grid-column:1/-1"><h3>No playlists yet</h3><p>Create one and add videos from the player.</p></div>`}</div></section>`;el.specialSection.querySelector('#newPlaylist').onclick=()=>{const n=prompt('Playlist name?');if(!n)return;state.playlists[n]=[];savePlaylists();renderSpecialView('playlists');toast('Playlist created')};el.specialSection.querySelector('#exportData').onclick=exportVaultData;el.specialSection.querySelector('#importData').onclick=importVaultData;el.specialSection.querySelectorAll('[data-playlist]').forEach(b=>b.onclick=()=>openPlaylist(b.dataset.playlist))}else if(kind==='stats'){const watched=Object.values(state.watch).filter(w=>w?.completedAt).length;const watchSec=Object.values(state.watch).reduce((a,w)=>a+(Number(w.position)||0),0);const memberCounts={};Object.values(state.history).forEach(v=>(v.tags||[]).forEach(t=>memberCounts[t]=(memberCounts[t]||0)+1));const top=Object.entries(memberCounts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—';el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Personal fan stats</div><h1 class="page-title">Your Vault</h1><p class="page-subtitle">Everything below stays on this device unless you export it.</p></div><div class="statbar"><div class="stat-card"><div class="stat-label">Opened</div><div class="stat-value">${Object.keys(state.history).length}</div><div class="stat-sub">history entries</div></div><div class="stat-card"><div class="stat-label">Completed</div><div class="stat-value">${watched}</div><div class="stat-sub">videos finished</div></div><div class="stat-card"><div class="stat-label">Saved</div><div class="stat-value">${state.myList.size}</div><div class="stat-sub">My List</div></div><div class="stat-card"><div class="stat-label">Favorites</div><div class="stat-value">${state.favorites.size}</div><div class="stat-sub">personal picks</div></div><div class="stat-card"><div class="stat-label">Watch time</div><div class="stat-value">${Math.floor(watchSec/3600)}h</div><div class="stat-sub">tracked locally</div></div><div class="stat-card"><div class="stat-label">Top tag</div><div class="stat-value">${esc(top)}</div><div class="stat-sub">from your history</div></div></div></section>`}else if(kind==='health'){el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Source monitoring</div><h1 class="page-title">Vault Health</h1><p class="page-subtitle">Source status helps us spot broken archives before they become a browsing problem.</p></div><div id="healthGrid" class="source-health"><div class="empty-hero" style="grid-column:1/-1">Checking source health…</div></div></section>`;api('/api/source-health').then(d=>{el.specialSection.querySelector('#healthGrid').innerHTML=d.sources.map(s=>`<article class="health-card"><div><div class="health-name">${esc(s.name)}</div><div class="health-meta">${s.videoCount||0} videos · ${s.lastSuccess?'updated '+new Date(s.lastSuccess).toLocaleString():'not checked yet'}</div></div><div class="health-status ${s.status==='healthy'?'healthy':s.status==='error'?'error':'warning'}">● ${esc(s.status)}</div></article>`).join('')}).catch(()=>{el.specialSection.querySelector('#healthGrid').innerHTML='<div class="empty-hero" style="grid-column:1/-1"><h3>Health check unavailable</h3><p>The public catalog can still work normally.</p></div>'})}else if(kind==='backup'){el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Local control</div><h1 class="page-title">Backup & Restore</h1><p class="page-subtitle">Export your local lists, playlists, favorites, history, queue, and watch progress as a JSON file.</p></div><div class="list-tools"><button class="btn btn-primary" id="backupExport">Export JSON</button><button class="btn btn-secondary" id="backupImport">Import JSON</button><button class="btn btn-tertiary" id="clearLocal">Clear local data</button></div></section>`;el.specialSection.querySelector('#backupExport').onclick=exportVaultData;el.specialSection.querySelector('#backupImport').onclick=importVaultData;el.specialSection.querySelector('#clearLocal').onclick=()=>{if(!confirm('Clear all BINI Vault data stored on this browser?'))return;['bini-vault-list','bini-vault-list-snapshots','bini-vault-watch','bini-vault-history','bini-vault-favorites','bini-vault-playlists','bini-vault-queue','bini-vault-notifications'].forEach(k=>localStorage.removeItem(k));location.reload()}}}
function openPlaylist(name){const items=(state.playlists[name]||[]).map(k=>state.allLoaded.get(k)||state.listSnapshots[k]||state.history[k]).filter(Boolean);el.specialSection.innerHTML=`<section class="section"><div class="page-intro"><div class="page-eyebrow">Playlist</div><h1 class="page-title">${esc(name)}</h1><p class="page-subtitle">${items.length} saved videos.</p></div>${items.length?`<div class="video-grid">${items.map(card).join('')}</div>`:`<div class="empty-hero"><h3>This playlist is empty</h3></div>`}</section>`;bindCards(el.specialSection);observeThumbs(el.specialSection)}
function exportVaultData(){const payload={version:1,exportedAt:new Date().toISOString(),list:[...state.myList],listSnapshots:state.listSnapshots,watch:state.watch,history:state.history,favorites:[...state.favorites],playlists:state.playlists,queue:state.queue};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`bini-vault-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exported')}
function importVaultData(){const input=document.createElement('input');input.type='file';input.accept='application/json';input.onchange=async()=>{try{const data=JSON.parse(await input.files[0].text());if(data.list)state.myList=new Set(data.list);if(data.listSnapshots)state.listSnapshots=data.listSnapshots;if(data.watch)state.watch=data.watch;if(data.history)state.history=data.history;if(data.favorites)state.favorites=new Set(data.favorites);if(data.playlists)state.playlists=data.playlists;if(data.queue)state.queue=data.queue;saveList();saveFavorites();savePlaylists();saveQueue();localStorage.setItem('bini-vault-watch',JSON.stringify(state.watch));localStorage.setItem('bini-vault-history',JSON.stringify(state.history));renderCurrentView();toast('Backup imported')}catch{toast('Invalid backup file')}};input.click()}
function clearModalPlayer(){if(ytSaveTimer)clearInterval(ytSaveTimer);ytSaveTimer=null;if(ytPlayer){try{saveYouTubeProgress();ytPlayer.destroy()}catch{}ytPlayer=null}}
function saveYouTubeProgress(){if(!ytPlayer||!state.selected)return;try{const t=ytPlayer.getCurrentTime();if(Number.isFinite(t)&&t>=0)saveWatch(state.selected,t)}catch{}}
function createYouTubePlayer(v,id,start){el.player.innerHTML='<div id="yt-player"></div>';const boot=()=>{if(!window.YT||!YT.Player){setTimeout(boot,250);return}ytPlayer=new YT.Player('yt-player',{videoId:id,playerVars:{autoplay:1,rel:0,modestbranding:1,playsinline:1,start:Math.max(0,Math.floor(start||0))},events:{onReady:()=>{if(start>0)try{ytPlayer.seekTo(start,true)}catch{};ytSaveTimer=setInterval(saveYouTubeProgress,4000)},onStateChange:e=>{if(e.data===YT.PlayerState.ENDED)markWatched(v)}}})};boot()}
function openModal(v){clearModalPlayer();state.selected=v;saveHistory(v);saveWatch(v,state.watch[key(v)]?.position||0);el.modalTitle.textContent='Now playing';el.modalTitleLarge.textContent=v.title;el.modalMeta.innerHTML=`${meta(v)}${v.date?` • ${esc(v.date)}`:''}${v.alternateSources?.length?` • ${v.alternateSources.length+1} sources`:''}`;el.modalDesc.textContent=strip(v.description||'No description available.');el.listBtn.textContent=state.myList.has(key(v))?'✓ In My List':'＋ My List';el.listBtn.classList.toggle('active',state.myList.has(key(v)));el.favoriteBtn.textContent=state.favorites.has(key(v))?'♥ Favorite':'♡ Favorite';el.favoriteBtn.classList.toggle('active',state.favorites.has(key(v)));el.markWatchedBtn.textContent=state.watch[key(v)]?.completedAt?'✓ Watched':'Mark as Watched';el.speedBtn.textContent=`${state.playerSpeed}×`;el.player.innerHTML='';const start=Number(state.watch[key(v)]?.position||0);if(isYT(v.url))createYouTubePlayer(v,ytId(v.url),start);else if(isDirect(v.url)){const video=document.createElement('video');video.controls=true;video.autoplay=true;video.playsInline=true;video.src=v.url;video.playbackRate=state.playerSpeed;const pos=start;video.addEventListener('loadedmetadata',()=>{if(pos>5&&pos<video.duration-5)video.currentTime=pos});video.addEventListener('timeupdate',()=>saveWatch(v,video.currentTime));video.addEventListener('ended',()=>markWatched(v));el.player.append(video)}else if(v.url){el.player.innerHTML=`<div style="padding:40px;text-align:center;color:#cfd3da">This source opens externally.<br><button class="small-btn" id="openExternal" style="margin-top:12px">Open source</button></div>`;byId('openExternal').onclick=()=>window.open(v.url,'_blank','noopener,noreferrer')}else el.player.innerHTML='<div style="padding:40px;text-align:center;color:#8e95a1">No playable source is available.</div>';renderQueue();renderRelated(v);el.modal.classList.remove('hidden');document.body.classList.add('modal-open');const next=findNextVideo(v);el.nextBtn.textContent=next?'Next ▶':'Close';el.nextBtn.onclick=()=>{const n=state.queue.length?nextQueued():findNextVideo(state.selected);if(n)openModal(n);else closeModal()}}
function closeModal(){clearModalPlayer();el.modal.classList.add('hidden');el.player.innerHTML='';el.relatedSection.innerHTML='';el.queueSection.innerHTML='';document.body.classList.remove('modal-open')}
function markWatched(v=state.selected){if(!v)return;const k=key(v),prev=state.watch[k]||{};state.watch[k]={...prev,position:parseDuration(v.duration||'')||prev.position||0,startedAt:prev.startedAt||Date.now(),updatedAt:Date.now(),completedAt:Date.now(),duration:v.duration||prev.duration||null,title:v.title,sourceName:v.sourceName,sourceId:v.sourceId,id:v.id,thumbnail:v.thumbnail,descriptionImage:v.descriptionImage,youtubeId:v.youtubeId,url:v.url,date:v.date,tags:v.tags,canonicalKey:v.canonicalKey};localStorage.setItem('bini-vault-watch',JSON.stringify(state.watch));el.markWatchedBtn.textContent='✓ Watched';toast('Marked as watched');renderStats();renderContinue()}
function toggleList(v=state.selected){if(!v)return;const k=key(v);if(state.myList.has(k)){state.myList.delete(k);delete state.listSnapshots[k];toast('Removed from My List')}else{state.myList.add(k);state.listSnapshots[k]=v;toast('Added to My List')}saveList();el.listBtn.textContent=state.myList.has(k)?'✓ In My List':'＋ My List';el.listBtn.classList.toggle('active',state.myList.has(k));renderStats();renderMyListHome()}
function toggleFavorite(v=state.selected){if(!v)return;const k=key(v);if(state.favorites.has(k)){state.favorites.delete(k);toast('Removed from favorites')}else{state.favorites.add(k);toast('Added to favorites')}saveFavorites();el.favoriteBtn.textContent=state.favorites.has(k)?'♥ Favorite':'♡ Favorite';el.favoriteBtn.classList.toggle('active',state.favorites.has(k));renderStats()}
function addToPlaylist(v=state.selected){if(!v)return;const names=Object.keys(state.playlists);const choice=prompt(names.length?`Playlist name (existing or new)\n${names.join(', ')}`:'Playlist name?','Favorites');if(!choice)return;const name=choice.trim();if(!name)return;if(!state.playlists[name])state.playlists[name]=[];const k=key(v);if(!state.playlists[name].includes(k))state.playlists[name].push(k);savePlaylists();toast(`Added to ${name}`)}
async function showQRCode(v=state.selected){if(!v)return;const url=`${location.origin}${location.pathname}?video=${encodeURIComponent(v.sourceId)}:${encodeURIComponent(v.id)}`;if(!window.QRCode){await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/qrcode@1.5.4/build/qrcode.min.js';sc.onload=resolve;sc.onerror=reject;document.head.appendChild(sc)})}const canvas=document.createElement('canvas');try{await QRCode.toCanvas(canvas,url,{width:230,margin:1,color:{dark:'#111111',light:'#ffffff'}});el.player.insertAdjacentHTML('afterend','');const box=document.createElement('div');box.style.cssText='display:grid;place-items:center;padding:22px;border-top:1px solid rgba(255,255,255,.08);background:#fff';box.append(canvas);const close=document.createElement('button');close.className='small-btn';close.style.marginTop='12px';close.textContent='Close QR';close.onclick=()=>box.remove();box.append(close);el.player.parentElement.insertBefore(box,el.player.nextSibling)}catch{toast('QR code unavailable')}}
function addToQueue(v=state.selected){if(!v)return;const k=key(v);if(!state.queue.includes(k))state.queue.push(k);saveQueue();renderQueue();toast(state.queue.includes(k)?'Added to queue':'Already in queue')}
function nextQueued(){const k=state.queue.shift();saveQueue();return k?(state.allLoaded.get(k)||state.listSnapshots[k]||state.history[k]):null}
function renderQueue(){const items=state.queue.map(k=>state.allLoaded.get(k)||state.listSnapshots[k]||state.history[k]).filter(Boolean);el.queueSection.innerHTML=items.length?`<div class="queue"><div class="section-head"><div class="section-title"><h2 style="font-size:15px">Up next</h2><p>${items.length} queued</p></div><button class="icon-link" id="clearQueue">Clear</button></div><div class="queue-list">${items.map(v=>`<div class="queue-item"><b>${esc(v.title)}</b><button data-remove-queue="${esc(key(v))}">×</button></div>`).join('')}</div></div>`:'';el.queueSection.querySelector('#clearQueue')?.addEventListener('click',()=>{state.queue=[];saveQueue();renderQueue()});el.queueSection.querySelectorAll('[data-remove-queue]').forEach(b=>b.onclick=()=>{state.queue=state.queue.filter(k=>k!==b.dataset.removeQueue);saveQueue();renderQueue()})}
function renderRelated(v){const related=sortVideos([...state.allLoaded.values()].filter(x=>key(x)!==key(v)&&(x.sourceId===v.sourceId||(v.tags||[]).some(t=>(x.tags||[]).includes(t))))).slice(0,4);el.relatedSection.innerHTML=related.length?`<section class="section" style="margin-top:20px"><div class="section-head"><div class="section-title"><h2 style="font-size:18px">More like this</h2><p>Keep exploring the Vault.</p></div></div><div class="mini-grid">${related.map(card).join('')}</div></section>`:'';bindCards(el.relatedSection);observeThumbs(el.relatedSection)}
function findNextVideo(v){const matches=sortVideos(currentMatches());const i=matches.findIndex(x=>key(x)===key(v));return i>=0&&i<matches.length-1?matches[i+1]:null}
function renderHero(v){if(!v)return;const img=sourceHero(v);el.heroBackdrop.classList.remove('loaded');el.heroBackdrop.src=img;el.heroBackdrop.onload=()=>el.heroBackdrop.classList.add('loaded');el.heroBackdrop.onerror=()=>{el.heroBackdrop.src=brandImage(v)};const tags=(v.tags||[]).slice(0,3).map(t=>`<span class="tech-pill">${esc(t)}</span>`).join('');const w=state.watch[key(v)],progress=w?.position&&parseDuration(v.duration||'')<1e8?Math.min(100,w.position/parseDuration(v.duration)*100):0;el.heroCopy.innerHTML=`<div class="kicker"><i></i>${esc(v.sourceName||'BINI Vault')}</div><h1>${esc(v.title||'BINI moment')}</h1><div class="hero-meta"><span>${esc(v.date||'Archive')}</span><span>•</span><span>${esc(v.duration||'Video')}</span>${v.year?`<span>•</span><span>${esc(v.year)}</span>`:''}</div>${tags?`<div class="hero-tech">${tags}</div>`:''}<p class="hero-desc">${esc(strip(v.description||'A curated moment from the BINI archive.'))}</p><div class="hero-actions"><button class="btn btn-primary" id="heroPlay">▶ ${progress?'Resume':'Watch Now'}</button><button class="btn btn-secondary" id="heroList">${state.myList.has(key(v))?'✓ In My List':'＋ My List'}</button><button class="btn btn-tertiary" id="heroShare">Share</button></div><div class="hero-credit">Archive source · ${esc(v.sourceName||'BINI Vault')}</div><div class="hero-controls"><button class="hero-arrow" id="heroPrev">‹</button><button class="hero-arrow" id="heroNext">›</button><div class="hero-dots"><span class="hero-dot active"></span><span class="hero-dot"></span><span class="hero-dot"></span><span class="hero-dot"></span></div></div>`;byId('heroPlay').onclick=()=>openModal(v);byId('heroList').onclick=()=>toggleList(v);byId('heroShare').onclick=()=>shareVideo(v);byId('heroPrev').onclick=()=>cycleHero(-1);byId('heroNext').onclick=()=>cycleHero(1)}
function setHero(v){state.heroVideo=v;renderHero(v)}function cycleHero(delta){const items=sortVideos([...state.allLoaded.values()]).slice(0,8);if(!items.length)return;state.heroIndex=(state.heroIndex+delta+items.length)%items.length;setHero(items[state.heroIndex])}
function startHeroTimer(){clearInterval(heroTimer);heroTimer=setInterval(()=>{if(state.view==='home'&&document.visibilityState==='visible')cycleHero(1)},9000)}
function renderLoadingShell(){el.heroCopy.innerHTML='<div class="hero-skeleton"><div class="skeleton-text" style="width:120px"></div><div class="skeleton-text" style="width:68%;height:48px;margin-top:15px"></div><div class="skeleton-text" style="width:48%;margin-top:12px"></div><div style="display:flex;gap:8px;margin-top:18px"><span class="skeleton-text" style="width:90px;height:34px"></span><span class="skeleton-text" style="width:100px;height:34px"></span></div></div>';el.tabs.innerHTML='';el.actions.innerHTML='';el.stats.innerHTML='';el.content.innerHTML=`<section class="section"><div class="video-grid grid-loading">${Array.from({length:12},()=>'<div class="skeleton-video"><div class="skeleton-thumb"></div><div class="skeleton-text"></div><div class="skeleton-text short"></div></div>').join('')}</div></section>`}
function renderErrorState(){el.content.innerHTML='<div class="empty-hero"><div class="empty-icon">!</div><h3>We couldn’t load the Vault</h3><p>Something interrupted the connection. Your saved library stays safe on this device.</p><button class="btn btn-primary" id="retryBtn">Try again</button></div>';byId('retryBtn').onclick=init}
function renderCurrentView(){const archive=state.view!=='home';el.main.classList.toggle('archive-main',archive);el.hero.classList.toggle('view-hidden',state.view!=='home');el.browsebar.classList.toggle('view-hidden',!['home','browse'].includes(state.view));el.stats.classList.add('view-hidden');el.continueSection.classList.add('view-hidden');el.myListSection.classList.add('view-hidden');el.historySection.classList.add('view-hidden');el.onThisDaySection.classList.add('view-hidden');el.collectionsSection.classList.add('view-hidden');el.specialSection.classList.add('view-hidden');el.content.innerHTML='';el.sentinel.classList.add('view-hidden');if(state.view==='home'){renderHome();return}if(state.view==='browse'){el.content.classList.remove('view-hidden');el.stats.classList.remove('view-hidden');renderStats();renderTabs();renderActions();renderCatalog();el.sentinel.classList.remove('view-hidden');observeEnd();return}if(state.view==='list'){el.myListSection.classList.remove('view-hidden');renderMyListPage();return}if(state.view==='history'){el.historySection.classList.remove('view-hidden');renderHistoryPage();return}if(state.view==='collections'){el.collectionsSection.classList.remove('view-hidden');renderCollectionsPage();return}if(['members','timeline','playlists','stats','health','backup'].includes(state.view)){el.specialSection.classList.remove('view-hidden');renderSpecialView(state.view)}}
function setActiveNav(name){const map={home:el.home,browse:el.browse,collections:el.collections,list:el.listNav,history:el.historyNav};Object.entries(map).forEach(([k,b])=>b?.classList.toggle('active',k===name));el.mobileNav?.querySelectorAll('[data-mobile-nav]').forEach(b=>b.classList.toggle('active',b.dataset.mobileNav===name))}
function navHome(){state.view='home';state.query='';state.tag='';state.year='';state.source='all';state.member=null;state.myListMode=false;setActiveNav('home');renderCurrentView();if(state.allLoaded.size)setHero(firstMatchingLoaded());else loadPage(true);scrollTo({top:0,behavior:'smooth'})}function navBrowse(){state.view='browse';state.myListMode=false;setActiveNav('browse');renderCurrentView();if(!state.videos.length)loadPage(true);scrollTo({top:0,behavior:'smooth'})}function navCollections(){state.view='collections';setActiveNav('collections');renderCurrentView();scrollTo({top:0,behavior:'smooth'})}function navList(){state.view='list';state.myListMode=true;setActiveNav('list');renderCurrentView();scrollTo({top:0,behavior:'smooth'})}function navHistory(){state.view='history';state.myListMode=false;setActiveNav('history');renderCurrentView();scrollTo({top:0,behavior:'smooth'})}
function collectionName(){return SOURCE_LABELS[state.source]||'BINI Videos'}function surpriseMe(){let pool=currentMatches();pool=pool.filter(v=>!state.watch[key(v)]?.completedAt);if(!pool.length)pool=currentMatches();if(!pool.length){toast('Load a few videos first');return}openModal(pool[Math.floor(Math.random()*pool.length)])}
function searchNow(){state.query=el.searchInput.value.trim();state.tag='';state.year='';state.member=null;state.source='all';state.view='browse';setActiveNav('browse');renderCurrentView();loadPage(true);el.searchSuggestions.classList.add('hidden');scrollTo({top:0,behavior:'smooth'});if(state.query)toast(`Searching for “${state.query}”`)}function showSearchSuggestions(value){const q=value.trim().toLowerCase(),rec=['Mikha','Maloi','Live','Pantropiko','Concert'];const base=q?rec.filter(x=>x.toLowerCase().includes(q)):rec;el.searchSuggestions.innerHTML=`<div class="suggestion-title">${q?'Suggestions':'Popular searches'}</div>${base.slice(0,5).map(x=>`<button class="suggestion" data-suggest="${esc(x)}">⌕ ${esc(x)}</button>`).join('')}`;el.searchSuggestions.classList.toggle('hidden',!base.length);el.searchSuggestions.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{el.searchInput.value=b.dataset.suggest;searchNow()})}
async function shareVideo(v){const url=`${location.origin}${location.pathname}?video=${encodeURIComponent(v.sourceId)}:${encodeURIComponent(v.id)}`;try{await navigator.clipboard.writeText(url);toast('Share link copied')}catch{prompt('Copy this link',url)}}
async function resolveSharedVideo(){const p=new URLSearchParams(location.search).get('video');if(!p)return;const [sourceId,id]=p.split(':');if(!sourceId||!id)return;try{const data=await api(`/api/video/${encodeURIComponent(sourceId)}/${encodeURIComponent(id)}`);if(data.video)openModal(data.video)}catch{}}
function openCommand(){el.command.classList.remove('hidden');el.commandInput.value='';renderCommand('');el.commandInput.focus()}function closeCommand(){el.command.classList.add('hidden')}function renderCommand(q){const items=[['Search videos','Open Browse search','search'],['Continue Watching','Open your current videos','continue'],['My List','Open saved videos','list'],['History','Open recently opened videos','history'],['Members','Explore member pages','members'],['Collections','Explore curated collections','collections'],['Playlists','Open personal playlists','playlists'],['Era Timeline','Browse archive history','timeline'],['Vault Health','Check source health','health'],['Backup & Restore','Export or import local data','backup']];const f=items.filter(([a,b])=>`${a} ${b}`.toLowerCase().includes(q.toLowerCase()));el.commandList.innerHTML=f.map(([a,b,k])=>`<button class="command-item" data-command="${k}"><span><b>${a}</b><br><small>${b}</small></span><span>↵</span></button>`).join('');el.commandList.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{closeCommand();const k=b.dataset.command;if(k==='search'){el.search.classList.add('open');el.searchInput.focus()}else if(k==='continue'){navHome();scrollTo({top:420,behavior:'smooth'})}else if(k==='list')navList();else if(k==='history')navHistory();else if(k==='members'||k==='timeline'||k==='playlists'||k==='health'||k==='backup')state.view=k;else state.view=k;setActiveNav(state.view);renderCurrentView()})}
function renderNotifications(){const notes=state.notifications.slice(0,12);el.notificationList.innerHTML=notes.length?notes.map(n=>`<div class="notification"><b>${esc(n.title)}</b><p>${esc(n.body)}</p></div>`).join(''):'<div class="notification"><b>You’re all caught up.</b><p>New archive activity will appear here.</p></div>';el.notifyDot.classList.toggle('hidden',!notes.length)}function addNotification(title,body){state.notifications.unshift({id:Date.now(),title,body});state.notifications=state.notifications.slice(0,30);localStorage.setItem('bini-vault-notifications',JSON.stringify(state.notifications));renderNotifications()}
function updateFreshNotification(){const now=Date.now();const last=Number(localStorage.getItem('bini-vault-last-seen')||0);if(last&&now-last>86400000)addNotification('BINI Vault is ready for another visit','Your saved history, list, and playlists are still on this device.');localStorage.setItem('bini-vault-last-seen',String(now))}
function cycleSpeed(){const vals=[0.75,1,1.25,1.5,2];const i=vals.indexOf(state.playerSpeed);state.playerSpeed=vals[(i+1)%vals.length];localStorage.setItem('bini-vault-speed',String(state.playerSpeed));el.speedBtn.textContent=`${state.playerSpeed}×`;if(ytPlayer){try{ytPlayer.setPlaybackRate(state.playerSpeed)}catch{}}else{const v=el.player.querySelector('video');if(v)v.playbackRate=state.playerSpeed}}
function togglePiP(){const v=el.player.querySelector('video');if(!v||!document.pictureInPictureEnabled){toast('Picture-in-picture is unavailable for this video');return}v.requestPictureInPicture().catch(()=>toast('Picture-in-picture unavailable'))}
window.__navList=navList;window.__navCollections=navCollections;window.__openByKey=k=>{const v=state.allLoaded.get(k)||state.listSnapshots[k]||state.history[k];if(v)openModal(v)};
el.searchToggle.onclick=()=>{el.search.classList.toggle('open');if(el.search.classList.contains('open'))el.searchInput.focus()};el.searchInput.onkeydown=e=>{if(e.key==='Enter')searchNow();if(e.key==='Escape'){el.searchInput.value='';el.searchSuggestions.classList.add('hidden')}};el.searchInput.oninput=()=>{el.searchClear.classList.toggle('hidden',!el.searchInput.value);showSearchSuggestions(el.searchInput.value)};el.searchClear.onclick=()=>{el.searchInput.value='';el.searchClear.classList.add('hidden');el.searchSuggestions.classList.add('hidden');searchNow()};el.home.onclick=navHome;el.browse.onclick=navBrowse;el.collections.onclick=navCollections;el.listNav.onclick=navList;el.historyNav.onclick=navHistory;el.brand.onclick=e=>{e.preventDefault();navHome()};el.surpriseBtn.onclick=surpriseMe;el.statsBtn.onclick=()=>{state.view='stats';renderCurrentView();setActiveNav('home');scrollTo({top:0,behavior:'smooth'})};el.moreBtn.onclick=()=>{el.moreMenu.classList.toggle('hidden');el.notificationPanel.classList.add('hidden')};el.moreMenu.querySelectorAll('[data-more]').forEach(b=>b.onclick=async()=>{const k=b.dataset.more;el.moreMenu.classList.add('hidden');if(k==='install'){if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;toast('Install prompt closed')}else toast('Your browser will show install options when available');return}state.view=k;renderCurrentView();setActiveNav('home');scrollTo({top:0,behavior:'smooth'})});el.notifyBtn.onclick=()=>{el.notificationPanel.classList.toggle('hidden');el.moreMenu.classList.add('hidden');renderNotifications()};el.clearNotifications.onclick=()=>{state.notifications=[];localStorage.setItem('bini-vault-notifications','[]');renderNotifications()};el.modalClose.onclick=closeModal;el.modal.onclick=e=>{if(e.target===el.modal)closeModal()};el.listBtn.onclick=()=>toggleList();el.favoriteBtn.onclick=()=>toggleFavorite();el.markWatchedBtn.onclick=()=>markWatched();el.speedBtn.onclick=cycleSpeed;el.pipBtn.onclick=togglePiP;el.shareBtn.onclick=()=>shareVideo(state.selected);el.queueBtn.onclick=()=>addToQueue();el.playlistBtn.onclick=()=>addToPlaylist();el.qrBtn.onclick=()=>showQRCode();el.nextBtn.onclick=()=>{const n=state.queue.length?nextQueued():findNextVideo(state.selected);if(n)openModal(n);else closeModal()};el.mobileNav?.querySelectorAll('[data-mobile-nav]').forEach(b=>b.onclick=()=>{const n=b.dataset.mobileNav;if(n==='home')navHome();else if(n==='browse')navBrowse();else if(n==='collections')navCollections();else if(n==='list')navList();else {el.moreMenu.classList.toggle('hidden')}});
el.commandInput.oninput=()=>renderCommand(el.commandInput.value);el.commandInput.onkeydown=e=>{if(e.key==='Escape')closeCommand()};el.command.onclick=e=>{if(e.target===el.command)closeCommand()};el.topbar.addEventListener('click',()=>{});window.addEventListener('scroll',()=>el.topbar.classList.toggle('scrolled',scrollY>24));el.topbar.classList.toggle('scrolled',window.scrollY>24);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();el.search.classList.add('open');el.searchInput.focus()}if(e.key==='Escape'&&!el.modal.classList.contains('hidden'))closeModal();if(!el.modal.classList.contains('hidden')){if(e.code==='Space'&&el.player.querySelector('video')){e.preventDefault();const v=el.player.querySelector('video');v.paused?v.play():v.pause()}if(e.key.toLowerCase()==='f'){const v=el.player.querySelector('video');v?.requestFullscreen?.()}if(e.key.toLowerCase()==='m'){const v=el.player.querySelector('video');if(v)v.muted=!v.muted}if(e.key.toLowerCase()==='n')el.nextBtn.click();if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const v=el.player.querySelector('video');if(v){e.preventDefault();v.currentTime=Math.max(0,Math.min(v.duration||1e9,v.currentTime+(e.key==='ArrowLeft'?-5:5)))}}if(e.key==='ArrowUp'||e.key==='ArrowDown'){const v=el.player.querySelector('video');if(v){e.preventDefault();v.volume=Math.max(0,Math.min(1,v.volume+(e.key==='ArrowUp'?.05:-.05)))}}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e});
async function init(){renderLoadingShell();renderNotifications();try{await api('/api/sources');state.view='home';setActiveNav('home');await loadPage(true);startHeroTimer();updateFreshNotification();await resolveSharedVideo();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}catch(e){console.error(e);renderErrorState(e)}}
init();
